#' @describeIn update Update method for \code{sim.LCA} objects
#' @importFrom utils modifyList
#' @export
update.sim.LCA <- function(object, ...) {
  arguments.current <- object$arguments
  arguments.new <- .update.arguments(
    arguments.current, list(...), sim.LCA, "sim.LCA"
  )

  sim.updated <- sim.LCA(
    N = arguments.new$N,
    I = arguments.new$I,
    L = arguments.new$L,
    poly.value = arguments.new$poly.value,
    IQ = arguments.new$IQ,
    distribution = arguments.new$distribution,
    params = arguments.new$params,
    is.sort=arguments.new$is.sort
  )
  return(sim.updated)
}

